<?php
require_once __DIR__.'/config.php';$pageTitle='Academic Q&A forum';$search=trim((string)($_GET['q']??''));$subject=valid_id($_GET['subject']??0);$subjects=$pdo->query('SELECT id,name FROM subjects ORDER BY name')->fetchAll();
$sql="SELECT q.*,u.name author,s.name subject_name,(SELECT COUNT(*) FROM answers a WHERE a.question_id=q.id AND a.status='visible') answer_count FROM questions q JOIN users u ON u.id=q.user_id LEFT JOIN subjects s ON s.id=q.subject_id WHERE q.status='visible'";$args=[];
if($search!==''){$sql.=" AND (q.title LIKE ? OR q.body LIKE ?)";$like='%'.$search.'%';$args=[$like,$like];}if($subject){$sql.=" AND q.subject_id=?";$args[]=$subject;}$sql.=" ORDER BY q.created_at DESC";$stmt=$pdo->prepare($sql);$stmt->execute($args);$questions=$stmt->fetchAll();
require __DIR__.'/includes/header.php';?>
<section class="page-hero"><div class="container"><span class="eyebrow">LEARN OUT LOUD</span><h1>Questions are how we grow.</h1><p>Ask about a tricky concept, share an explanation, and help your classmates move forward.</p></div></section><div class="page-content"><div class="container"><div class="toolbar"><form class="search-form"><input type="search" name="q" value="<?= e($search) ?>" placeholder="Search questions…"><select name="subject"><option value="0">All subjects</option><?php foreach($subjects as $s): ?><option value="<?= (int)$s['id'] ?>" <?= $subject===(int)$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach; ?></select><button class="btn btn-primary">Search</button></form><?php if(current_user()): ?><a class="btn btn-primary" href="ask.php">＋ Ask a question</a><?php else: ?><a class="btn btn-primary" href="login.php">Log in to ask</a><?php endif; ?></div>
<?php if($questions): ?><div class="content-stack"><?php foreach($questions as $q): ?><article class="card question-row"><div class="vote-count"><?= (int)$q['answer_count'] ?><br><small>answers</small></div><div><h3><a href="question.php?id=<?= (int)$q['id'] ?>"><?= e($q['title']) ?></a></h3><p><?= e(excerpt($q['body'],220)) ?></p><div class="resource-meta"><span><?= e($q['subject_name']??'General') ?></span><span>·</span><span>Asked by <?= e($q['author']) ?></span><span>·</span><span><?= e(date('M j, Y',strtotime($q['created_at']))) ?></span></div></div></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><div class="empty-icon">💬</div><h3>No questions match yet</h3><p>Try a different search, or be the first to ask your community.</p><?php if(current_user()): ?><a class="btn btn-primary" href="ask.php">Ask a question</a><?php endif; ?></div><?php endif; ?></div></div>
<?php require __DIR__.'/includes/footer.php';?>
